import { describe, it, expect } from "vitest";
import { quote, claim } from "./claim-office.js";

describe("MHPCO quote - base premiums and fee", () => {
  it.todo("empty item list -> premium 5 G (only processing fee)");
  it.todo("single sword -> base 100 + 5 fee = 105 G");
  it.todo("single amulet -> base 60 + 5 fee = 65 G");
  it.todo("single staff -> base 80 + 5 fee = 85 G");
  it.todo("single potion -> base 40 + 5 fee = 45 G");
  it.todo("single rune (component) -> base 25 + 5 fee = 30 G");
  it.todo("single moonstone (component) -> base 25 + 5 fee = 30 G");
});

describe("MHPCO quote - component blocks", () => {
  it.todo("2 runes -> 50 G base (+5 fee = 55 G)");
  it.todo("3 runes -> 60 G base block (+5 fee = 65 G)");
  it.todo("4 runes -> 100 G base, no block (+5 fee = 105 G)");
  it.todo("7 runes -> 175 G base (+5 fee = 180 G)");
  it.todo("2 runes + 1 moonstone -> 75 G base, no block, different types (+5 fee = 80 G)");
  it.todo("3 runes + 3 moonstones -> 120 G base, two separate blocks (+5 fee = 125 G)");
});

describe("MHPCO quote - item-specific modifiers", () => {
  it.todo("cursed sword -> +50% of item base: 150 + 5 fee = 155 G");
  it.todo("high-enchantment sword (ench 5) -> +30%: 130 + 5 fee = 135 G");
  it.todo("sword ench 4 -> no high-enchantment surcharge: 100 + 5 fee = 105 G");
  it.todo("cursed sword ench 5 -> both surcharges: 100+50+30=180 + 5 = 185 G");
});

describe("MHPCO quote - policy-wide modifiers", () => {
  it.todo("loyalty: customer exactly 2 years -> 20% discount on policy base");
  it.todo("customer < 2 years -> no loyalty discount");
  it.todo("first insurance (first contract) -> +10% on policy base");
  it.todo("follow-up contract (after first) -> -15% on policy base");
});

describe("MHPCO quote - modifier scope on multi-item policies", () => {
  it.todo("cursed sword + plain amulet -> curse applies to sword base only: 160 + 50 = 210 (+ ...)");
});

describe("MHPCO quote - rounding in favor (up)", () => {
  it.todo("premium yielding 197.5 -> 198 G (rounded up)");
  it.todo("intermediate amounts kept as fractions, only final rounded");
});

describe("MHPCO quote - integration examples", () => {
  it.todo("newcomer with cursed sword (0 yrs, first) -> 165 G");
  it.todo("long-standing customer 2nd contract, cursed sword ench 7 -> 160 G");
});

describe("MHPCO quote - errors", () => {
  it.todo("unknown item type -> throws error");
});

describe("MHPCO claim - deductible and basic reimbursement", () => {
  it.todo("regular sword steel ench 3, damage 500 -> payout 400 (minus 100 deductible)");
  it.todo("rune damage 200 -> payout 100 (minus 100 deductible, no special clause)");
});

describe("MHPCO claim - special clauses", () => {
  it.todo("high enchantment >= 8: sword ench 8 damage 1000 -> 50% then deductible = 400");
  it.todo("dragon material: full reimbursement then deductible");
  it.todo("dragon + ench 9, damage 1000 -> 50% rule wins: 400");
  it.todo("dragon ench 5, damage 800 -> dragon clause only: 700");
  it.todo("steel ench 9, damage 1000 -> high-enchantment only: 400");
});

describe("MHPCO claim - multiple damages and deductible per event", () => {
  it.todo("dragon attack sword 500 + amulet 300 -> payout 600 (deductible per item)");
});

describe("MHPCO claim - cap", () => {
  it.todo("policy sword+amulet -> insurance sum 1600, cap 3200");
  it.todo("cursed sword cap based on unmodified value -> 2000");
  it.todo("policy sword + 3 runes block -> insurance sum 1750, cap 3500");
  it.todo("two successive 1500 claims on sword (cap 2000): first 1400 remaining 600, second 600 remaining 0");
});

describe("MHPCO claim - policy coverage validation", () => {
  it.todo("two swords insured -> both damaged, each own deductible");
  it.todo("more damages of a type than covered -> reject (throws)");
  it.todo("damage item not in policy -> throws");
  it.todo("negative damage amount -> throws");
});

describe("MHPCO claim - rounding in favor (down)", () => {
  it.todo("payout yielding 350.5 -> 350 G (rounded down)");
});

