import { describe, it, expect } from "vitest";
import { quote, claim, basePremium } from "./claim-office.js";

describe("basePremium - item base premiums", () => {
  it("empty item list -> 0 G base", () => {
    expect(basePremium([])).toBe(0);
  });
  it("single sword -> 100 G base", () => {
    expect(basePremium([{ type: "sword" }])).toBe(100);
  });
  it("single amulet -> 60 G base", () => {
    expect(basePremium([{ type: "amulet" }])).toBe(60);
  });
  it("single staff -> 80 G base", () => {
    expect(basePremium([{ type: "staff" }])).toBe(80);
  });
  it("single potion -> 40 G base", () => {
    expect(basePremium([{ type: "potion" }])).toBe(40);
  });
  it("single rune (component) -> 25 G base", () => {
    expect(basePremium([{ type: "rune" }])).toBe(25);
  });
  it("single moonstone (component) -> 25 G base", () => {
    expect(basePremium([{ type: "moonstone" }])).toBe(25);
  });
});

describe("basePremium - component blocks", () => {
  it("2 runes -> 50 G base", () => {
    expect(basePremium([{ type: "rune" }, { type: "rune" }])).toBe(50);
  });
  it("3 runes -> 60 G base block", () => {
    expect(basePremium([{ type: "rune" }, { type: "rune" }, { type: "rune" }])).toBe(60);
  });
  it("4 runes -> 100 G base, no block", () => {
    expect(basePremium(Array(4).fill({ type: "rune" }))).toBe(100);
  });
  it("7 runes -> 175 G base", () => {
    expect(basePremium(Array(7).fill({ type: "rune" }))).toBe(175);
  });
  it("2 runes + 1 moonstone -> 75 G base, no block (different types)", () => {
    expect(basePremium([{ type: "rune" }, { type: "rune" }, { type: "moonstone" }])).toBe(75);
  });
  it("3 runes + 3 moonstones -> 120 G base, two separate blocks", () => {
    expect(
      basePremium([
        { type: "rune" }, { type: "rune" }, { type: "rune" },
        { type: "moonstone" }, { type: "moonstone" }, { type: "moonstone" },
      ]),
    ).toBe(120);
  });
});

describe("basePremium - item-specific modifiers", () => {
  it("cursed sword -> +50% of item base: 150 G", () => {
    expect(basePremium([{ type: "sword", cursed: true }])).toBe(150);
  });
  it("high-enchantment sword (ench 5) -> +30%: 130 G", () => {
    expect(basePremium([{ type: "sword", enchantment: 5 }])).toBe(130);
  });
  it("sword ench 4 -> no high-enchantment surcharge: 100 G", () => {
    expect(basePremium([{ type: "sword", enchantment: 4 }])).toBe(100);
  });
  it("cursed sword ench 5 -> both surcharges: 100+50+30=180 G", () => {
    expect(basePremium([{ type: "sword", cursed: true, enchantment: 5 }])).toBe(180);
  });
  it("cursed sword + plain amulet -> curse on sword base only: 100+50+60=210 G", () => {
    expect(
      basePremium([{ type: "sword", cursed: true }, { type: "amulet" }]),
    ).toBe(210);
  });
});

describe("quote - policy-wide modifiers and fee", () => {
  it("empty item list -> premium 5 G (only processing fee)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [], 0)).toBe(5);
  });
  it("plain sword, first contract -> 100 +10% first +5 fee = 115 G", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword" }], 0)).toBe(115);
  });
  it("loyalty: 2 years, follow-up contract sword -> 100 -20% -15% +5 = 70 G", () => {
    expect(quote({ yearsWithMHPCO: 2 }, [{ type: "sword" }], 1)).toBe(70);
  });
  it("customer < 2 years, follow-up sword -> 100 -15% +5 = 90 G", () => {
    expect(quote({ yearsWithMHPCO: 1 }, [{ type: "sword" }], 1)).toBe(90);
  });
});

describe("quote - rounding in favor (up)", () => {
  it("premium yielding 197.5 -> 198 G (rounded up)", () => {
    // sword ench5 cursed base 180, follow-up -15% = 153, +5 = 158... construct 197.5:
    // staff base 80 + amulet 60 + sword 100 = 240; loyalty -20% = 192; not .5.
    // Use: sword cursed base 150, follow-up contract -15% = 127.5, +5 fee = 132.5 -> 133
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword", cursed: true }], 1)).toBe(133);
  });
});

describe("quote - integration examples", () => {
  it("newcomer with cursed sword (0 yrs, first) -> 165 G", () => {
    expect(
      quote({ yearsWithMHPCO: 0 }, [{ type: "sword", material: "steel", enchantment: 3, cursed: true }], 0),
    ).toBe(165);
  });
  it("long-standing 2nd contract, cursed sword ench 7 -> 160 G", () => {
    expect(
      quote({ yearsWithMHPCO: 3 }, [{ type: "sword", material: "steel", enchantment: 7, cursed: true }], 1),
    ).toBe(160);
  });
});

describe("quote - errors", () => {
  it("unknown item type -> throws error", () => {
    expect(() => quote({ yearsWithMHPCO: 0 }, [{ type: "broomstick" }], 0)).toThrow();
  });
});

describe("claim - deductible and basic reimbursement", () => {
  it("regular sword steel ench 3, damage 500 -> payout 400", () => {
    const policy = { items: [{ type: "sword", material: "steel", enchantment: 3 }] };
    expect(claim(policy, { cause: "fire", damages: [{ itemType: "sword", amount: 500 }] }, Infinity))
      .toMatchObject({ payout: 400 });
  });
  it("rune damage 200 -> payout 100 (no special clause)", () => {
    const policy = { items: [{ type: "rune" }] };
    expect(claim(policy, { cause: "fire", damages: [{ itemType: "rune", amount: 200 }] }, Infinity))
      .toMatchObject({ payout: 100 });
  });
});

describe("claim - special clauses", () => {
  it("high enchantment >= 8: sword ench 8 damage 1000 -> 50% then deductible = 400", () => {
    const policy = { items: [{ type: "sword", material: "steel", enchantment: 8 }] };
    expect(claim(policy, { cause: "x", damages: [{ itemType: "sword", amount: 1000 }] }, Infinity))
      .toMatchObject({ payout: 400 });
  });
  it("dragon material: full reimbursement then deductible (dragon ench 8 dmg 1000 -> 400)", () => {
    const policy = { items: [{ type: "sword", material: "dragon", enchantment: 8 }] };
    expect(claim(policy, { cause: "x", damages: [{ itemType: "sword", amount: 1000 }] }, Infinity))
      .toMatchObject({ payout: 400 });
  });
  it("dragon + ench 9, damage 1000 -> 50% rule wins: 400", () => {
    const policy = { items: [{ type: "sword", material: "dragon", enchantment: 9 }] };
    expect(claim(policy, { cause: "x", damages: [{ itemType: "sword", amount: 1000 }] }, Infinity))
      .toMatchObject({ payout: 400 });
  });
  it("dragon ench 5, damage 800 -> dragon clause only: 700", () => {
    const policy = { items: [{ type: "sword", material: "dragon", enchantment: 5 }] };
    expect(claim(policy, { cause: "x", damages: [{ itemType: "sword", amount: 800 }] }, Infinity))
      .toMatchObject({ payout: 700 });
  });
  it("steel ench 9, damage 1000 -> high-enchantment only: 400", () => {
    const policy = { items: [{ type: "sword", material: "steel", enchantment: 9 }] };
    expect(claim(policy, { cause: "x", damages: [{ itemType: "sword", amount: 1000 }] }, Infinity))
      .toMatchObject({ payout: 400 });
  });
});

describe("claim - multiple damages, deductible per event", () => {
  it("dragon attack sword 500 + amulet 300 -> payout 600", () => {
    const policy = { items: [{ type: "sword", material: "steel", enchantment: 3 }, { type: "amulet" }] };
    expect(
      claim(policy, { cause: "dragon", damages: [{ itemType: "sword", amount: 500 }, { itemType: "amulet", amount: 300 }] }, Infinity),
    ).toMatchObject({ payout: 600 });
  });
});

describe("claim - cap", () => {
  it("sword+amulet -> insurance sum 1600, cap 3200 (remaining after small claim)", () => {
    const policy = { items: [{ type: "sword", material: "steel", enchantment: 3 }, { type: "amulet" }] };
    const cap = 2 * (1000 + 600);
    expect(
      claim(policy, { cause: "x", damages: [{ itemType: "sword", amount: 500 }] }, cap),
    ).toMatchObject({ payout: 400, remainingCap: 3200 - 400 });
  });
  it("two successive 1500 claims on sword (cap 2000): first 1400/600, second 600/0", () => {
    const policy = { items: [{ type: "sword", material: "steel", enchantment: 3 }] };
    const first = claim(policy, { cause: "x", damages: [{ itemType: "sword", amount: 1500 }] }, 2000);
    expect(first).toMatchObject({ payout: 1400, remainingCap: 600 });
    const second = claim(policy, { cause: "x", damages: [{ itemType: "sword", amount: 1500 }] }, first.remainingCap);
    expect(second).toMatchObject({ payout: 600, remainingCap: 0 });
  });
});

describe("claim - policy coverage validation", () => {
  it("two swords insured -> both damaged, each own deductible (500+500 -> 800)", () => {
