  });
  it("rune damage 200 -> payout 100 (no special clause)", () => {
    const policy = { items: [{ type: "rune" }] };
    expect(claim(policy, { cause: "fire", damages: [{ itemType: "rune", amount: 200 }] }, Infinity))
      .toMatchObject({ payout: 100 });
  });
});

describe("claim - special clauses", () => {
  it("high enchantment >= 8: sword ench 8 damage 1000 -> 50% then deductible = 400", () => {
    const policy = { items: [{ type: "sword", material: "steel", enchantment: 8 }] };
    expect(claim(policy, { cause: "x", damages: [{ itemType: "sword", amount: 1000 }] }, Infinity))
      .toMatchObject({ payout: 400 });
  });
  it("dragon material: full reimbursement then deductible (dragon ench 8 dmg 1000 -> 400)", () => {
    const policy = { items: [{ type: "sword", material: "dragon", enchantment: 8 }] };
    expect(claim(policy, { cause: "x", damages: [{ itemType: "sword", amount: 1000 }] }, Infinity))
      .toMatchObject({ payout: 400 });
  });
  it("dragon + ench 9, damage 1000 -> 50% rule wins: 400", () => {
    const policy = { items: [{ type: "sword", material: "dragon", enchantment: 9 }] };
    expect(claim(policy, { cause: "x", damages: [{ itemType: "sword", amount: 1000 }] }, Infinity))
      .toMatchObject({ payout: 400 });
  });
  it("dragon ench 5, damage 800 -> dragon clause only: 700", () => {
    const policy = { items: [{ type: "sword", material: "dragon", enchantment: 5 }] };
    expect(claim(policy, { cause: "x", damages: [{ itemType: "sword", amount: 800 }] }, Infinity))
      .toMatchObject({ payout: 700 });
  });
  it("steel ench 9, damage 1000 -> high-enchantment only: 400", () => {
    const policy = { items: [{ type: "sword", material: "steel", enchantment: 9 }] };
    expect(claim(policy, { cause: "x", damages: [{ itemType: "sword", amount: 1000 }] }, Infinity))
      .toMatchObject({ payout: 400 });
  });
});

describe("claim - multiple damages, deductible per event", () => {
