    const policy = { items: [{ type: "sword", material: "steel", enchantment: 8 }] };
    expect(claim(policy, { cause: "x", damages: [{ itemType: "sword", amount: 901 }] }, Infinity))
      .toMatchObject({ payout: 350 });
  });
});

