});

describe("claim - multiple damages, deductible per event", () => {
  it.todo("sword 500 + amulet 300 -> 600");
});

describe("claim - cap", () => {
  it.todo("sword+amulet cap 3200, claim 500 -> payout 400 remaining 2800");
  it.todo("two 1500 claims on sword cap 2000 -> 1400/600 then 600/0");
});

